mapper.select:
SELECT jsonb_build_object( 'groupKey', g.group_key, 'fileCount', g.file_count, 'totalSize', g.total_size, 'recordCount', g.record_count )::text FROM ( SELECT
AS group_key, count(*) AS file_count, COALESCE(sum(ab.file_size), 0) AS total_size, count(DISTINCT ab.record_id) AS record_count
GROUP BY 1 ) g ORDER BY g.group_key LIMIT #{limit} OFFSET #{offset}

SELECT jsonb_build_object(
'recordId', g.record_id,
'fileCount', g.file_count,
'totalSize', g.total_size

    , 'lf${_labelIndex}', g.lf${_labelIndex}

)::text
FROM (
SELECT
t.${@com.richuang.os.nocode.runtime.dal.support.RuntimeSqlParameters@quote(base.keyColumn)}::text AS
record_id,
count(*) AS file_count,
COALESCE(sum(ab.file_size), 0) AS total_size

    , to_jsonb(t)->>${@com.richuang.os.nocode.runtime.dal.support.RuntimeSqlParameters@literal(_label.column)} AS
    lf${_labelIndex}




GROUP BY
t.${@com.richuang.os.nocode.runtime.dal.support.RuntimeSqlParameters@quote(base.keyColumn)}

    , to_jsonb(t)->>${@com.richuang.os.nocode.runtime.dal.support.RuntimeSqlParameters@literal(_label.column)}

) g
ORDER BY g.record_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM (
SELECT 1



GROUP BY t.${@com.richuang.os.nocode.runtime.dal.support.RuntimeSqlParameters@quote(base.keyColumn)}
) x

SELECT jsonb_build_object(
'nodeId', x.node_id,
'fileCount', x.file_count,
'totalSize', x.total_size
)::text
FROM (
SELECT ab.row_id AS node_id,
count(*) AS file_count,
COALESCE(sum(ab.file_size), 0) AS total_size



AND ab.record_id = #{recordId}
AND ab.detail_id = #{detailId}
GROUP BY ab.row_id
) x
ORDER BY x.node_id
LIMIT #{limit} OFFSET #{offset}

SELECT count(DISTINCT ab.row_id)



AND ab.record_id = #{recordId}
AND ab.detail_id = #{detailId}

SELECT jsonb_build_object(
'nodeId', x.node_id,
'fileCount', x.file_count,
'totalSize', x.total_size
)::text
FROM (
SELECT ab.field_id AS node_id,
count(*) AS file_count,
COALESCE(sum(ab.file_size), 0) AS total_size



AND ab.record_id = #{recordId}
AND ab.detail_id = #{detailId}
AND ab.row_id = #{rowId}
GROUP BY ab.field_id
) x
ORDER BY x.node_id

SELECT jsonb_build_object( 'fileId', ab.file_id::text, 'entryId', ab.entry_id::text, 'spaceId', ab.space_id::text, 'name', ab.file_name, 'size', ab.file_size, 'mimeType', ab.mime_type, 'submitter', ab.creator, 'uploadedAt', to_char(ab.create_time, 'YYYY-MM-DD HH24:MI:SS'), 'recordId', ab.record_id, 'detailId', ab.detail_id, 'rowId', ab.row_id, 'fieldId', ab.field_id, 'ruleVersion', rd.rule_version, 'groupKeys', rd.group_keys
)::text
ORDER BY ab.create_time DESC, ab.id DESC LIMIT #{limit} OFFSET #{offset}
